WelcomeScreen::WelcomeScreen(TFT_eSprite &_tft, StateMachine &_stateManager) : tft(&_tft), stateManager(&_stateManager)
{
  name = "WelcomeScreen";
}

void WelcomeScreen::enter()
{
  tft->fillScreen(0x0);
  tft->createSprite(240, 240);
  tft->fillSprite(TFT_BLACK);
  tft->setTextColor(0xFFFF);
  tft->setTextSize(1);
  tft->setFreeFont(&FreeSansBold18pt7b);
  tft->drawString("Welcome", string_1_x, 107);
  tft->pushImage(195, 105, 31, 31, image_paint_4_pixels);
  tft->pushImage(201, 110, 20, 20, image_output_onlinebitmaptools__1__pixels);
  tft->pushSprite(0, 0);
}
void WelcomeScreen::loop() {}
void WelcomeScreen::exit() {
  tft->deleteSprite();
  tft->fillScreen(0x0);
}
void WelcomeScreen::btnPress(String button)
{
  if (button == "RIGHT" && stateManager->states[1])
  {
    stateManager->changeState("ConfigScreen");
  }
}
